 if(provider==='الشاملة الرسمية (Windows)')return 'https://shamela.ws/search';
 if(provider==='أرشيف الإسكندرية (Windows)')return 'https://www.alexandria-archive.com/';
 if(provider==='DOAJ')return 'https://doaj.org/';
 if(provider==='OpenAlex')return 'https://openalex.org/';
 if(provider==='مخطوطات مالي الإسلامية'){q.set('q',query);return 'https://www.loc.gov/collections/islamic-manuscripts-from-mali/?'+q}
 if(provider==='المكتبة الرقمية العالمية'){q.set('q',query);return 'https://www.loc.gov/collections/world-digital-library/?'+q}
