 if(!confirm('ستشمل النسخة المشاريع المحفوظة وملفات المصادر المرتبطة بها فقط، حتى 64 ميبيبايت و100 ملف. الملف غير مشفر وقد يحتوي مواد خاصة؛ احفظه في مكان آمن. هل تتابع؟'))return;
 const button=e.currentTarget;backupBusy=true;button.disabled=true;
 try{const obj=await createFullBackup();download('sanad-backup-with-files.json',obj);alertToast(`أُنشئت نسخة تشمل ${obj.projects.length} مشروعًا و${obj.files.length} ملفًا مرتبطًا`)}catch(err){alertToast('تعذر إنشاء النسخة: '+err.message)}finally{backupBusy=false;button.disabled=false}
